-- V5 — bookmark.memo → note 이름 변경의 1단계(넓히기). 서비스를 멈추지 않으려고 한 번에 RENAME하지 않는다.
-- 새 컬럼을 NULL 허용으로 추가하고 지금 값을 복사만 한다. 옛 서버는 memo만 읽고 쓰므로 아무 영향이 없다.
-- 다음 배포(같은 커밋의 코드)는 memo·note 둘 다에 쓰고 읽기는 아직 memo다.
ALTER TABLE bookmark ADD COLUMN note VARCHAR(200) NULL AFTER memo;

UPDATE bookmark SET note = memo;

package org.example.bookmark;

import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class BookmarkDualWriteStageTest {
    @Autowired MockMvc mvc;
    @Autowired JdbcTemplate jdbc;
    @Autowired EntityManager em;

    @Test
    void putAndPatchWriteBothColumns() throws Exception {
        mvc.perform(put("/api/posts/2/bookmark")
                .header("Authorization", "Bearer tok-kimjava")
                .contentType("application/json")
                .content("{\"memo\":\"dual-put\"}"))
                .andExpect(status().isOk());
        assertBoth("dual-put");
        mvc.perform(patch("/api/posts/2/bookmark")
                .header("Authorization", "Bearer tok-kimjava")
                .contentType("application/json")
                .content("{\"memo\":\"dual-patch\"}"))
                .andExpect(status().isOk());
        assertBoth("dual-patch");
        mvc.perform(patch("/api/posts/2/bookmark")
                .header("Authorization", "Bearer tok-kimjava")
                .contentType("application/json")
                .content("{\"memo\":null}"))
                .andExpect(status().isOk());
        assertBoth(null);
    }

    private void assertBoth(String expected) {
        em.flush();
        var rows = jdbc.queryForList("SELECT memo, note FROM bookmark WHERE member_id=2 AND post_id=2");
        assertEquals(1, rows.size());
        assertEquals(expected, rows.get(0).get("memo"));
        assertEquals(expected, rows.get(0).get("note"));
    }
}

